-- New syllabus edition for this career/year (2025, distinct from the 2021
-- edition already registered).
insert into public.syllabus_editions (contest_name,role_name,contest_year,exam_board,source_id)
select 'Polícia Federal','Papiloscopista Policial Federal',2025,'CEBRASPE',(select id from public.content_sources where url=$q$https://drive.google.com/file/d/1oYY4L2FMusSyNcMxoegVSD3GrMndqTm3/view$q$)
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Papiloscopista Policial Federal' and contest_year=2025
);

with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Papiloscopista Policial Federal' and contest_year=2025
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ($q$Língua Portuguesa$q$,$q$Compreensão e interpretação de texto de opinião sobre narrativas policiais no cinema, na literatura e na televisão; aspectos linguísticos: coesão, coerência, morfossintaxe e reescrita de frases.$q$),
  ($q$Redação Oficial$q$,$q$Manual de Redação da Presidência da República: impessoalidade dos expedientes oficiais e pronomes de tratamento (endereçamento, vocativo e corpo do texto).$q$),
  ($q$Direito Administrativo$q$,$q$Atributos dos atos administrativos (presunção de veracidade e autoexecutoriedade), responsabilidade civil do Estado por atos de servidores, sociedades de economia mista e empresas públicas, regime disciplinar do servidor público e licitação (inexigibilidade por segurança nacional).$q$),
  ($q$Direito Constitucional$q$,$q$Direitos e garantias fundamentais (sigilo de correspondência e comunicações), formas e sistemas de governo, organização da segurança pública, atribuições constitucionais da Polícia Federal e da Polícia Rodoviária Federal, proteção aos indígenas e ao meio ambiente.$q$),
  ($q$Direito Penal$q$,$q$Código Penal: crime de prevaricação, causas de aumento de pena no roubo, aplicação da lei penal no espaço (extraterritorialidade em alto-mar).$q$),
  ($q$Direito Processual Penal$q$,$q$Inquérito policial: instauração mediante requerimento do ofendido e por notitia criminis de qualquer pessoa do povo.$q$),
  ($q$Direitos Humanos$q$,$q$Regras Mínimas das Nações Unidas para o Tratamento de Presos (Regras de Mandela): registro de bens pessoais, trabalho prisional, separação de categorias de presos e direito de recurso a instância superior.$q$),
  ($q$Direito Internacional$q$,$q$Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes (extradição de torturadores) e Convenção Relativa ao Estatuto dos Refugiados (não expulsão).$q$),
  ($q$Legislação Penal Especial$q$,$q$Estatuto da Criança e do Adolescente (medida socioeducativa), Lei de Migração (prisão cautelar para extradição), Lei de Drogas (apreensão e destinação de bens) e Lei de Tortura (regime inicial de cumprimento de pena).$q$),
  ($q$Legislação Especial - Segurança Pública e Identificação Civil$q$,$q$Segurança privada (competência da Polícia Federal para renovar autorização de funcionamento), Lei do Estatuto do Desarmamento (comunicação de extravio de arma de fogo), Lei de repressão a crimes interestaduais/internacionais e Serviço de Identificação do Cidadão (Decreto n.º 11.797/2023).$q$),
  ($q$Direito Ambiental$q$,$q$Lei de Crimes Ambientais (Lei n.º 9.605/1998): natureza da ação penal nas infrações lesivas ao meio ambiente.$q$),
  ($q$Estatística e Probabilidade$q$,$q$Distribuição normal e soma de variáveis aleatórias, mediana e desvio padrão; regressão linear simples, coeficiente de correlação de Pearson e intervalo de confiança para diferença de médias.$q$),
  ($q$Raciocínio Lógico-Matemático$q$,$q$Tabelas-verdade e conectivos lógicos, lógica de argumentação com testemunhos, proposições condicionais compostas, negação de sentenças, probabilidade e princípio da casa dos pombos, contagem com repetição.$q$),
  ($q$Informática$q$,$q$Internet e intranet, redes de computadores e segurança da informação, computação em nuvem, teoria geral de sistemas, modelagem entidade-relacionamento e bancos de dados relacionais (SQL, transações ACID), biometria (FPIR/FNIR), Python, modelo OSI, DNS, autenticação multifator, machine learning e APIs (REST/GraphQL).$q$),
  ($q$Biologia Aplicada à Papiloscopia$q$,$q$Metabolismo energético celular (glicólise e via das pentoses fosfato), fecundação/segmentação/gastrulação, genética de grupos sanguíneos (ABO e MN) e tecido epitelial.$q$),
  ($q$Física Aplicada à Papiloscopia$q$,$q$Circuitos elétricos, campo elétrico e movimento oscilatório, capacitores e óptica geométrica/ondulatória (lei de Snell, resolução de microscópio e dispersão em prisma).$q$),
  ($q$Química Aplicada à Papiloscopia$q$,$q$Estequiometria da combustão completa do álcool etílico (conservação de átomos, massa molar, balanceamento e cálculo de massa de produto) e propriedades coligativas (pressão osmótica, osmose, solução saturada e ponto de fusão de soluções).$q$)
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note) as (values
(2025,1,$q$Língua Portuguesa$q$,$q$O texto sugere que o gênero policial é o preferido do público na literatura, na televisão e no cinema.$q$,$q$O texto sugere que o gênero policial é o preferido do público na literatura, na televisão e no cinema.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,2,$q$Língua Portuguesa$q$,$q$Entende-se da leitura do texto que a frequente transposição da narrativa de best-sellers para as telas da televisão e do cinema se justifica pela expectativa de repetição do sucesso obtido na venda das respectivas obras literárias.$q$,$q$Entende-se da leitura do texto que a frequente transposição da narrativa de best-sellers para as telas da televisão e do cinema se justifica pela expectativa de repetição do sucesso obtido na venda das respectivas obras literárias.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,3,$q$Língua Portuguesa$q$,$q$A partir das ideias de Carlos Gerbase reproduzidas no texto, conclui-se que as histórias narradas em livros e filmes podem nortear a conduta social de leitores e espectadores.$q$,$q$A partir das ideias de Carlos Gerbase reproduzidas no texto, conclui-se que as histórias narradas em livros e filmes podem nortear a conduta social de leitores e espectadores.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,4,$q$Língua Portuguesa$q$,$q$O termo "crescente" (segundo período do primeiro parágrafo) poderia ser substituído, sem prejuízo do sentido original do texto, por considerável.$q$,$q$O termo "crescente" (segundo período do primeiro parágrafo) poderia ser substituído, sem prejuízo do sentido original do texto, por considerável.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,5,$q$Língua Portuguesa$q$,$q$No segundo período do segundo parágrafo, a oração "que as histórias têm começo, meio e fim" classifica-se sintaticamente como subordinada adjetiva restritiva.$q$,$q$No segundo período do segundo parágrafo, a oração "que as histórias têm começo, meio e fim" classifica-se sintaticamente como subordinada adjetiva restritiva.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,6,$q$Língua Portuguesa$q$,$q$A supressão da vírgula empregada após "personagem" (primeiro período do terceiro parágrafo) prejudicaria a correção gramatical do texto.$q$,$q$A supressão da vírgula empregada após "personagem" (primeiro período do terceiro parágrafo) prejudicaria a correção gramatical do texto.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,7,$q$Língua Portuguesa$q$,$q$No segundo parágrafo, o intercambiamento das expressões "Logo" (terceiro período) e "Além disso" (quarto período), embora alterasse as relações coesivas entre os períodos, manteria a coerência das ideias do texto.$q$,$q$No segundo parágrafo, o intercambiamento das expressões "Logo" (terceiro período) e "Além disso" (quarto período), embora alterasse as relações coesivas entre os períodos, manteria a coerência das ideias do texto.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,8,$q$Língua Portuguesa$q$,$q$O pronome presente no termo "nela" (último parágrafo) tem como referente "a narrativa policial".$q$,$q$O pronome presente no termo "nela" (último parágrafo) tem como referente "a narrativa policial".$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,9,$q$Redação Oficial$q$,$q$Os assuntos objetos dos expedientes oficiais devem ser tratados de forma estritamente impessoal, uma vez que a redação oficial é elaborada sempre em nome do serviço público e em atendimento ao interesse geral dos cidadãos.$q$,$q$Os assuntos objetos dos expedientes oficiais devem ser tratados de forma estritamente impessoal, uma vez que a redação oficial é elaborada sempre em nome do serviço público e em atendimento ao interesse geral dos cidadãos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,10,$q$Redação Oficial$q$,$q$Na redação oficial, os pronomes de tratamento são empregados em três contextos: endereçamento, vocativo e corpo do texto.$q$,$q$Na redação oficial, os pronomes de tratamento são empregados em três contextos: endereçamento, vocativo e corpo do texto.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,11,$q$Direito Administrativo$q$,$q$A presunção de veracidade dos atos administrativos refere-se aos fatos, ou seja, presumem-se verdadeiros os fatos alegados pela administração pública, ao passo que a autoexecutoriedade constitui atributo pelo qual os atos administrativos se impõem a terceiros, independentemente de sua concordância.$q$,$q$A presunção de veracidade dos atos administrativos refere-se aos fatos, ou seja, presumem-se verdadeiros os fatos alegados pela administração pública, ao passo que a autoexecutoriedade constitui atributo pelo qual os atos administrativos se impõem a terceiros, independentemente de sua concordância.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,12,$q$Direito Administrativo$q$,$q$A pessoa que sofrer algum dano por ato praticado por um servidor público no exercício da função poderá ajuizar ação de indenização somente contra o Estado.$q$,$q$A pessoa que sofrer algum dano por ato praticado por um servidor público no exercício da função poderá ajuizar ação de indenização somente contra o Estado.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,13,$q$Direito Administrativo$q$,$q$As sociedades de economia mista e as empresas públicas desempenham atividade de natureza econômica e se distinguem pela forma de organização e pela composição do capital.$q$,$q$As sociedades de economia mista e as empresas públicas desempenham atividade de natureza econômica e se distinguem pela forma de organização e pela composição do capital.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,14,$q$Direito Administrativo$q$,$q$O cancelamento do registro da penalidade de suspensão de servidor público, que ocorre após o decurso de dois anos de efetivo exercício, surtirá efeitos retroativos caso o servidor não pratique, nesse período, nova infração disciplinar.$q$,$q$O cancelamento do registro da penalidade de suspensão de servidor público, que ocorre após o decurso de dois anos de efetivo exercício, surtirá efeitos retroativos caso o servidor não pratique, nesse período, nova infração disciplinar.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
(2025,15,$q$Direito Administrativo$q$,$q$É inexigível a licitação para a contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministério da Defesa, mediante demanda dos comandos das Forças Armadas.$q$,$q$É inexigível a licitação para a contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministério da Defesa, mediante demanda dos comandos das Forças Armadas.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_CB2_01/106_PF_CG1_01/106_PF_017_01 (Cargo 17 - Papiloscopista Policial Federal, PF 2025, Edital nº 1 - PF - Policial de 20/05/2025, retificado pelo Edital nº 9 de 16/09/2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos.xlsm (blocos CB2, CG1 e 106_PF_017_01, cargo Papiloscopista). Base legal/científica ainda não conferida individualmente em fonte oficial — aguardando revisão item a item antes de content_status=active.$q$),
