), editions as (
  select id,contest_year from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Papiloscopista Policial Federal' and contest_year=2025
), source_map as (
  select imported.item_number,
    case
      when imported.item_number between 1 and 60 then 'Prova objetiva PF 2025 - Conhecimentos Básicos Bloco I (CB2)'
      when imported.item_number between 61 and 96 then 'Prova objetiva PF 2025 - Conhecimentos Básicos Bloco II (CG1)'
      else 'Prova objetiva PF 2025 - Papiloscopista (Conhecimentos Específicos)'
    end question_source_title,
    case
      when imported.item_number between 1 and 60 then 'Gabarito definitivo PF 2025 - Conhecimentos Básicos Bloco I (CB2)'
      when imported.item_number between 61 and 96 then 'Gabarito definitivo PF 2025 - Conhecimentos Básicos Bloco II (CG1)'
      else 'Gabarito definitivo PF 2025 - Papiloscopista (Conhecimentos Específicos)'
    end answer_source_title
  from imported
), resolved as (
  select imported.*, question_source.id question_source_id, answer_source.id answer_key_source_id, topic.id syllabus_topic_id
  from imported
  join source_map on source_map.item_number=imported.item_number
  join editions on editions.contest_year=imported.exam_year
  join public.syllabus_topics topic on topic.edition_id=editions.id and topic.discipline=imported.subject and topic.topic_order=1
  join public.content_sources question_source on question_source.title=source_map.question_source_title
  join public.content_sources answer_source on answer_source.title=source_map.answer_source_title
)
insert into public.official_exam_questions (
  question_source_id,answer_key_source_id,syllabus_topic_id,contest_name,career_name,exam_board,exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
)
select question_source_id,answer_key_source_id,syllabus_topic_id,'Polícia Federal','Papiloscopista Policial Federal','CEBRASPE',exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
from resolved
on conflict (contest_name,career_name,exam_year,item_number) do nothing;
